sys_variable_value.value:
(function execute(inputs, outputs) {
    var gr_data_source = new GlideRecord('sys_data_source');
    gr_data_source.initialize();
    gr_data_source.sys_scope = inputs.scope;
    gr_data_source.name = inputs.name;
    gr_data_source.import_set_table_name = inputs.import_set_table_name;
    gr_data_source.type = inputs.type;
    gr_data_source.format = inputs.format;
    gr_data_source.file_retrieval_method = inputs.file_retrieval_method;
    gs.info("Create Data Source: calling insert");
    var data_source_sys_id = gr_data_source.insert();
    gs.info("Create Data Source: " + data_source_sys_id);
    outputs.data_source_sys_id = data_source_sys_id;
})(inputs, outputs);

